function sign(value){return crypto.createHmac('sha256',sessionSecret).update(value).digest('base64url');}
function createSession(user){const payload=Buffer.from(JSON.stringify({user,exp:Math.floor(Date.now()/1000)+sessionSeconds,nonce:crypto.randomBytes(12).toString('base64url')})).toString('base64url');return `${payload}.${sign(payload)}`;}
